-- ds_dimension_scores — GENERATED by tools/build_production.py from tools/dashboard_datasets.py.
-- Paste into the dashboard's Data tab as a dataset named ds_dimension_scores.
-- One row per scheduled run and DQ dimension: rows checked and failed by the active checks of that dimension, its score, and how many of them breach. Executive summary's By DQ dimension tiles until 2026-10-21; kept for Genie. No threshold: a threshold belongs to a key attribute, not to a dimension.

WITH attached AS (                      -- active rules on a registered key attribute
  SELECT DISTINCT x.rule_id
  FROM   sdpt_data_trnf.udp_brnz.dq_results_v_cde_coverage cv LATERAL VIEW explode(cv.rule_ids) x AS rule_id
),
k AS (
  SELECT c.run_id, c.rule_id, c.status, c.rows_scanned, c.violation_count,
         ROW_NUMBER() OVER (PARTITION BY c.run_id, c.rule_id ORDER BY c.result_id) AS n
  FROM   sdpt_data_trnf.udp_brnz.dq_results_check_run c
  WHERE  c.status IN ('pass', 'breach')
),
d AS (
  SELECT k.*, CASE r.rule_type
         WHEN 'not_null' THEN 'Completeness'
         WHEN 'format' THEN 'Validity' WHEN 'sentinel' THEN 'Validity' WHEN 'variance' THEN 'Validity'
         WHEN 'consistency' THEN 'Consistency' WHEN 'referential' THEN 'Consistency'
         WHEN 'uniqueness' THEN 'Uniqueness' ELSE 'Other' END AS dimension
  FROM   k
  JOIN   attached a ON a.rule_id = k.rule_id
  JOIN   sdpt_data_trnf.udp_brnz.dq_config_v_rule_registry_current r ON r.rule_id = k.rule_id
  WHERE  k.n = 1
)
SELECT s.run_day, s.run_ts, s.is_latest, d.dimension,
       COUNT(*)                                                                 AS checks,
       COUNT_IF(d.status = 'breach')                                            AS checks_breaching,
       SUM(d.rows_scanned)                                                      AS rows_checked,
       SUM(d.violation_count)                                                   AS rows_failed,
       100.0 * (SUM(d.rows_scanned) - SUM(d.violation_count)) / SUM(d.rows_scanned) AS score_pct
FROM   d
JOIN   sdpt_data_trnf.udp_brnz.dq_results_v_scheduled_run s ON s.run_id = d.run_id
GROUP  BY s.run_day, s.run_ts, s.is_latest, d.dimension
-- Newest first, so a counter per dimension (widget filter dimension = ...) reads row 1.
ORDER  BY s.run_ts DESC, d.dimension
